import analyze, math, sys
from collections import deque

def render(segs, e1, e2, mean, scale=0.08, margin=8, dilate=2):
    P=[]
    for s in segs:
        a=[s[i]-mean[i] for i in range(3)]; b=[s[i+3]-mean[i] for i in range(3)]
        ua=sum(a[i]*e1[i] for i in range(3)); va=sum(a[i]*e2[i] for i in range(3))
        ub=sum(b[i]*e1[i] for i in range(3)); vb=sum(b[i]*e2[i] for i in range(3))
        P.append((ua,va,ub,vb))
    us=[];vs=[]
    for ua,va,ub,vb in P: us+=[ua,ub]; vs+=[va,vb]
    umin,umax=min(us),max(us); vmin,vmax=min(vs),max(vs)
    W=int((umax-umin)/scale)+2*margin+1
    H=int((vmax-vmin)/scale)+2*margin+1
    wall=bytearray(W*H)
    def mark(u,v):
        c=int(round((u-umin)/scale))+margin; r=int(round((vmax-v)/scale))+margin
        if 0<=r<H and 0<=c<W: wall[r*W+c]=1
    for ua,va,ub,vb in P:
        c1=(ua-umin)/scale+margin; r1=(vmax-va)/scale+margin
        c2=(ub-umin)/scale+margin; r2=(vmax-vb)/scale+margin
        dc=c2-c1; dr=r2-r1
        steps=max(1,int(max(abs(dc),abs(dr))*1.2))
        for k in range(steps+1):
            t=k/steps; mark(umin+(ua+(ub-ua)*t)+0, va+(vb-va)*t)
    # dilate
    if dilate>0:
        g2=bytearray(W*H)
        for r in range(H):
            for c in range(W):
                if wall[r*W+c]:
                    for dr in range(-dilate,dilate+1):
                        rr=r+dr
                        if 0<=rr<H:
                            base=rr*W
                            for dc in range(-dilate,dilate+1):
                                cc=c+dc
                                if 0<=cc<W: g2[base+cc]=1
        wall=g2
    # flood fill outside
    outside=bytearray(W*H)
    dq=deque()
    for c in range(W):
        for r in (0,H-1):
            i=r*W+c
            if not wall[i] and not outside[i]: outside[i]=1; dq.append(i)
    for r in range(H):
        for c in (0,W-1):
            i=r*W+c
            if not wall[i] and not outside[i]: outside[i]=1; dq.append(i)
    while dq:
        i=dq.popleft(); r=i//W; c=i%W
        if r>0:
            j=i-W
            if not wall[j] and not outside[j]: outside[j]=1; dq.append(j)
        if r<H-1:
            j=i+W
            if not wall[j] and not outside[j]: outside[j]=1; dq.append(j)
        if c>0:
            j=i-1
            if not wall[j] and not outside[j]: outside[j]=1; dq.append(j)
        if c<W-1:
            j=i+1
            if not wall[j] and not outside[j]: outside[j]=1; dq.append(j)
    # filled = not outside (walls count)
    return W,H,wall,outside,P,(umin,umax,vmin,vmax)

def ascii_out(W,H,outside,block=3):
    ow=W//block; oh=H//block
    lines=[]
    for br in range(oh):
        row=[]
        for bc in range(ow):
            cnt=0; tot=0
            for r in range(br*block,(br+1)*block):
                for c in range(bc*block,(bc+1)*block):
                    tot+=1
                    if not outside[r*W+c]: cnt+=1
            frac=cnt/tot
            row.append('#' if frac>0.45 else ('.' if frac>0.15 else ' '))
        lines.append(''.join(row).rstrip())
    return lines

if __name__=='__main__':
    segs=analyze.load()
    mean,cov,evals,evecs=analyze.pca(segs)
    e1,e2=evecs[2],evecs[1]
    W,H,wall,outside,P,rng=render(segs,e1,e2,mean,scale=0.08,dilate=2)
    print('W,H',W,H,'rng',rng,file=sys.stderr)
    lines=ascii_out(W,H,outside,block=3)
    print('lines',len(lines),'cols',max(len(x) for x in lines),file=sys.stderr)
    for l in lines: print(l)
EOF
